from itertools import combinations

def compute_nice_intersections(paths):
    intersections = 0
    for path in paths:
        count = 0
        max_count = 0
        for i in range(1, len(path)):
            for j in range(i + 1, len(path)):
                moves = path[j] == path[-1]
                if moves and count > max_count:
                    intersections += 1
                    max_count = count
                count += 2
    return intersections

def count_nice_ways(n, m, obstacles):
    total_paths = 0
    for h1, l1, h2, l2 in combinations(range(1, n), 2):
        if (h1, l1) in obstacles and (h2, l2) in obstacles:
            continue
        left_steps = h1 + h2
        down_steps = l1 + l2
        leftway = (total_paths - compute_nice_intersections([k for k in range(h1 + 1, n + 1) if (k, l1) not in obstacles]) % 1000000007
        rightway = (total_paths + compute_nice_intersections([k for k in range(h2 + 1, m + 1) if (k, l2) not in obstacles]) % 1000000007
        can_arrive = abs(l1 - l2) + min(h1, h2)
        if not can_arrive:
            continue
        total_paths += leftway * rightway % 1000000007
        if total_paths >= 1000000007:
            total_paths %= 1000000007
    return total_paths

