def can_first_player_win(test_cases, number_of_cases):
    for _ in range(number_of_cases):
        number_of_pairs = int(input())
        pairs = []
        for _ in range(number_of_pairs):
            a, b = map(int, input().split())
            if a > b:
                smaller = b
                larger = a
            else:
                smaller = a
                larger = b
            pairs.append((smaller, larger))

        winning_case = False
        def mirror_pairs(current_pairs):
            next_pairs = []
            for pair in current_pairs:
                smaller, larger = pair
                # Mirror the pair if both integers are equal
                if smaller == larger:
                    next_pairs.extend([(smaller, 0), (0, larger)])
                else:
                    next_pairs.extend([(smaller, x * smaller) for x in range(1, larger // smaller + 1)])
            return next_pairs

        pairs = pairs + pairs  # Mirror the pairs for both players
        current_pairs = pairs
        last_empty_pair = None
        while current_pairs and not winning_case:
            new_pairs = []
            for pair in current_pairs:
                if pair[0] * pair[1] == 0:
                    last_empty_pair = pair
                else:
                    smaller, larger = pair
                    # Mirror the pair if both integers are unequal and larger is not 0
                    if smaller != larger and larger != 0:
                        new_pairs.extend([(smaller, x * smaller) for x in range(1, larger // smaller + 1)])
                    if not (last_empty_pair and last_empty_pair[0] * last_empty_pair[1] == 0):
                        new_pairs.extend([(smaller, x * smaller) for x in range(1, larger // smaller + 1)])
            current_pairs = new_pairs
            winning_case = any((smaller, 0) in pairs for pair in current_pairs)

        return "YES" if winning_case else "NO"

