import fractions
from math import factorial

MOD = int(998244353)

def nCr(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

def p2(n, m1, m2):
    return (m1 * m2 * nCr(n, m2)) % MOD

def main():
    n = int(input().rstrip())
    a, b = map(int, input().split())
    m1 = (a * (b - 1)) // (n * (n - 1))
    m2 = (n - 1) // b
    memo = {}

    def game_distribution(n, m1, m2):
        if (n, m2) in memo:
            return memo[(n, m2)]
        if n == 1:
            return 1
        game_distribution(n - 1, n - m1, m2)
        return m1 * nCr(n - 1, m2) % MOD

    def mem_m(p, denominator, q):
        q = fractions.Fraction(q, denominator)
        dp = {}
        def search(p):
            if p not in dp:
                dp[p] = (p * nCr(n, n - p) + search(floor(p * n + denominator))) % MOD
            return dp[p]
        return search(p)

    answer = -(m1 + 1) % MOD
    i = 1
    while True:
        p = None
        while p < i:
            if mem_m(i - p, denominator, nCr(n, p - 1)) == answer // (p + 1):
                break
            p += 1
        if p != i:
            break
        answer = p2(i, p, answer)
        i = floor((answer + MOD - 1) / (p + 1))

    ans = (game_distribution(n, m1, m2) + answer) % MOD

    return print(ans)


