import math

def find_minimum_day(n, events):
    events.sort()
    left = [0] * (n+1)
    right = [0] * (n+1)
    result = float("inf")
    jobs_executed = 0

    for i, (start, end) in enumerate(events):
        left[i] = jobs_executed
        right[i] = jobs_executed + 1
        for j in range(i-1, -1, -1):
            if end <= events[j][1]:
                left[i] = min(left[i], left[j])
            else:
                break

    for i, (start, end) in enumerate(events):
        end += 1
        jobs_executed += 1
        result = min(result, end)
        for j in range(i, -1, -1):
            if start <= events[j][0] and end <= events[j][1]:
                if start > right[j]:
                    result = min(result, end)
                if end < left[j]:
                    result = min(result, end)
                left = [right[j]] + left
            else:
                break

    result += 1
    if n == 0:
        return 0
    elif result == float("inf"):
        return -1
    else:
        return result

