import sys

def f_number(x, k):
    res = x
    while x % k == 0 or x == 1:
        res >>= 1
        x >>= 1
    return res ^ 1

def restore_operations(n, k, nums):
    result = 1
    for i in range(n-1):
        x = f_number(nums[i], k)
        y = f_number(nums[i], k)
        while x and y and x > y:
            nums.remove(y)
            nums.remove(x)
            x = f_number(nums[0], k)
            y = f_number(nums[1], k)
        while x:
            nums.remove(x)
            x = f_number(nums[0], k)
            result += 1
    return result

def restore_operations_n(n, nums):
    m = [0] * n
    p = list(nums[:n//2])
    q = list(nums[n//2:])
    for i in p:
        if f_number(i, k) == 1:
            m[0] = f_number(i, k)
        else:
            m[0] = f_number(i, k)
    for j in range(1, n-1):
        if f_number(q[j], k) == 1:
            m[-j-1] = f_number(q[j], k)
        else:
            m[j] = f_number(q[j], k)
    for j in p:
        if f_number(q[-j], k) == 1:
            m[-1] = f_number(q[-j], k)
        else:
            m[-j-1] = f_number(q[-j], k)
    ans = 0
    for i in range(n):
        ans += len(list(filter(lambda x: (f_number(x, k) ^ i) == 0, nums)))
    return ans

