        if i not in seen:
            seen.add(i)
            helper(adj, i)

    result = set()
    for idx in range(n):
        results[idx] = results[idx][:]

    return len(seen) == len(adj)

class EulerianPathFinder:
    def __init__(self, edges):
        self.parents = [len(edges) + c for c in range(len(edges))]
        self.seen = set()
        self.triplets = 0
        self.down = collections.defaultdict(list)
        start = [i+1 for i in range(len(edges)) if dfs(i)]
        trunk = [None]*len(edges)

        def find_path(start_node, prev_node=None):
            self.seen.add(start_node)
            for child in range(len(edges[start_node])):
                if edges[start_node][child] != prev_node:
                    self.parents[child] = self.parents[start_node] + child
                    self.down[child].append(start_node)
                    find_path(edges[start_node][child], start_node)
            self.seen.remove(start_node)

        find_path(start[0])

    def add_edge(self, edge):
        self.triplets += len(self.seen) * len(self.seen)
        self.down[edge[0]].append(edge[1])
        self.triplets += self.parents[edge[1]]
        self.down[edge[1]].append(edge[0])
        self.triplets += self.parents[edge[0]]
        self.seen.add(edge[0])
        self.seen.add(edge[1])

