def digit_sum_base(n, k):
    return sum(n % (10**i) // (10**(i-1)) for i in range(20)) % (10**9 + 7)

def calculate_subsequences(n, k):
    if k == 1:
        return pow(n, n, (10**9 + 7))
    else:
        largest = str(n)
        for i in range(len(largest)):
            largest += '0'
        largest = largest[:18] + '9' * ((len(largest) - 17) % k)  # Extend to make it divisible by k
        total = n * (k - 1) + (2**(k-1) - 2)  # Calculate remaining length of number
        ans = sum(digit_sum_base(x, k) * (2**total // (x ** (i+1)) % (10**9 + 7)) for i, x in enumerate(largest.split())) % (10**9 + 7)
        return ans % (10**9 + 7)

