import sys

def earliest_day_of_completion(n, exams):
    stack = []
    events = [(0, -1), (1, 1)]  # (day, 0 if for first attempt, 1 if for second attempt)

    for day in range(1, n + 2):
        for exam in exams:
            if exam[0] <= day <= exam[1]:
                events.append((day, 0))
            else:
                events.append((day, 1))

        # Process events
        while events and events[0][0] <= day:
            if events[0][1] == 0:
                earliest_event = events[0]
            else:
                earliest_event = events.pop(0)
                stack.append(earliest_event)

        # Handle stacks
        if stack:
            earliest_event = stack.pop()
            if earliest_event[0] == day and earliest_event[1] == 1:
                events.append((day, 0))

        events.sort()

    earliest_day = 0
    for day, action in events:
        if action == 0:
            earliest_day = max(earliest_day, day)
            continue
        earliest_day = max(earliest_day, 2 * day)
    return earliest_day

