def count_paths(n, m, ob_table):
    mod = 1000000007
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[1][1] = 2  # Initial state
    for y in range(1, m + 1):
        if ob_table[y-1][0] == '#':
            dp[1][y] = 0  # Blocked path for turtle 1
        else:
            dp[1][y] = 1  # Opening path for turtle 1

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if ob_table[i-1][j-1] == '#':
                dp[i][j] = dp[i-1][j] + dp[i][j-1]  # Current block moves collision not allowed
            else:
                dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % mod  # Current collision possible

