import math
mod = int(1e9) + 7

def sum_of_digits(number, base):
    return sum(int(digit) for digit in str(number))

def get_k_subsequences(number, base, k):
    if k == 1:
        return pow(base, number, mod)

    # For k > 1, number starts forming subsequence by decimal numbers up to 10^k-1
    multiplier_base = math.pow(base, number, mod)
    consecutive = math.pow(base, k, mod)
    return (multiplier_base + mod - 1) * get_k_subsequences(number - 1, base, k - 1) % mod

def calculate_augmented_representation_mod(number, k):
    if k == 1:
        return math.log(number, 10) + 1

    # Use Mann-Multiplication approach to compute number in binary modulo k-based
    original = number
    low_b_places = math.pow(2, calculate_augmented_representation_mod(number, k-1))
    high_b_places = low_b_places * 2
    reduced = number // high_b_places
    non_redundant = n - reduced * (high_b_places // 2)
    return non_redundant + calculate_augmented_representation_mod(reduced, k - 1)

def compute_subsequence_count(n, k):
    sum_k = calculate_augmented_representation_mod(n, k)
    return (get_k_subsequences(sum_k, k, k) ** 2) % mod

def solution(x):
    return compute_subsequence_count(int(x), int(30))

