                if points[i][1] - points[j][1] >= y2 - y1:
                    # point [i] is closer to the window window or points[j] closer
                    if y2 <= max(points[i][1], points[j][1]):
                        if points[i][1] == points[j][1] and points[i][0] == points[j][0]:
                            # case of vertical line, if both point add to count
                            return len(points[i]) // 2
                        elif points[i][0] == j or points[j][0] == i:
                            # case of line parallel to the x-axis
                            return 1
                elif points[j][1] - points[i][1] >= y2 - y1:
                    # point [j] is closer to the window window or points[i] closer
                    if points[i][1] == points[j][1] and points[i][0] == points[j][0]:
                        return 1
                    elif points[j][0] == i or points[i][0] == j:
                        return 1
            elif points[i][1] == points[j][1]:
                # horizontal line contains points[i] and points[j]
                if points[i][0] - points[j][0] >= x2 - x1:
                    # point [i] is closer to the window window or points[j] closer
                    if x2 <= max(points[i][0], points[j][0]):
                        if points[i][0] == points[j][0] and points[i][1] == points[j][1]:
                            # case of horizontal line, if both point add to count
                            return len(points[i]) // 2
                        elif points[i][1] == i or points[j][1] == j:
                            # case of line parallel to the y-axis
                            return 1
                elif points[j][0] - points[i][0] >= x2 - x1:
                    # point [j] is closer to the window window or points[i] closer
                    if x2 <= max(points[i][0], points[j][0]):
