import sys

def is_vertical_line(x1, x2):
    return x1 < x2

def is_horizontal_line(y1, y2):
    return y1 < y2

def is_parallel_to(coord1, coord2, coord3, coord4):
    return (is_vertical_line(coord1[0], coord2[0]) and is_parallel_vertical_to(coord3[0], coord4[0], coord1[0], coord2[0])) or (is_horizontal_line(coord1[1], coord2[1]) and is_parallel_horizontal_to(coord3[1], coord4[1], coord1[1], coord2[1]))

def is_parallel_horizontal_to(x1, x2, y, z):
    return x1 == x2 and is_equal(x1, x2, y, z)

def is_parallel_vertical_to(y1, y2, x, z):
    return y1 == y2 and is_equal(y1, y2, x, z)

def is_equal(x1, x2, y, z):
    return abs(x1 - x2) == abs(y - z)

def bfs(start, end, grid):
    visited = set()
    queue = [start]
    height_map = dict()
    height_map[start] = ((0, 0))

    while queue:
        current = queue.pop(0)

        for neighbor in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_height = (current[0] + neighbor[0], current[1] + neighbor[1])

            if (new_height not in height_map) or height_map[new_height] != (0, 0):
                continue

            if end == new_height or (0, 0) in grid and grid[0][0] == 0:
                return True

            if new_height not in visited:
                visited.add(new_height)
                queue.append(new_height)
                height_map[new_height] = ((current[0], current[1]), height_map[current])

    return False

