import sys
from bisect import bisect_left

def shift_matrix(row):
    shift_index = 0
    for i in range(1, len(row)):
        if row[i-1] < row[i]:
            shift_index = i
    return shift_index, ''.join(row[shift_index:] + row[:shift_index])

def min_operations(query):
    queries = [(i, shift_matrix(query[i:i+len(row)])) for i, row in enumerate(rows)]
    queries.sort(key=lambda x: x[1][0])
    qualified_rows = [(row, max(bisect_left(shift_index_range, i), bisect_left(shift_index_range, len(query)-i))) for i, (_, shift_index_range) in queries]
    qualified_rows.sort(key=lambda x: (x[1][1], x[1][0]))

    min_operations = sys.maxsize
    for operations in range(len(query)):
        if qualified_rows[-1][1][1] + operations < len(rows):
            min_operations = min(min_operations, operations)
        for i in range(qualified_rows[-1][1][1], len(qualified_rows)):
            if qualified_rows[i][1][1] < len(rows):
                temp = (qualified_rows[i][1][1] + (qualified_rows[i][1][1] - qualified_rows[i][0][1])) // len(query)
                if qualified_rows[i][0][0] + temp < len(rows):
                    min_operations = min(min_operations, operations + temp)
    return min_operations if qualified_rows[-1][1][1] + operations == len(rows) else -1

def main():
    n, m, q = map(int, input().split())
    rows = [list(input()) for _ in range(n)]
    queries = [input() for _ in range(q)]
    for query in queries:
        print(min_operations(query))

if __name__ == "__main__":
