from math import factorial
from typing import List

MOD = 1000000007

def countPaths(n: int, m: int, board: List[str]) -> int:
    total_paths = 1
    start = 0
    end = m - 1
    chars = {'.', '#'}

    for i in range(n):
        for j in board[i]:
            if end and j == '#' and board[i][end - 1] != '#':
                total_paths *= factorial(n + 1/*start, j//2 - start])
                total_paths *= factorial(end + 1/*j + 1, m - end + 1/*j//2 - end*/)
                total_paths %= MOD
                start, end = j + 1, end - j
            else:
                if j not in chars:
                    start, end = j + 1, m - 1
                    while end > start and board[i][end] == '#' and board[i][end - 1] == '#':
                        end -= 1
                elif j == '#':
                    return 0
                else:
                    total_paths *= (m - end)//(start - (j))
                    total_paths %= MOD
                    start, end = start + 1, end

    return total_paths

def main():
    n, m = map(int, input().split())
    board = [input() for _ in range(n)]
    print(countPaths(n, m, board))

