                if i != j and j != k and i != k:
                    if j != i and j != k and i != j:
                        matrix[i][j] += matrix[i-1][k] * binomial_coefficient(k-1, min(k-1,i-1)) % mod

    res = 0
    for i in range(n+1):
        res += matrix[i][n]
    return res

n = int(input())
print(table_placements(n))
