from functools import lru_cache
from math import gcd

# Input debugging
def debug_input(n, k, numbers):
    print(f"n: {n}, k: {k}")
    for num in numbers:
        print(num, end=" ")
    print()

# Remove leading zeros from numbers
def remove_leading_zeros(a_list):
    while True:
        max_index = -1
        for i, num in enumerate(a_list):
            if num != 0:
                max_index = i
                break
        if max_index == -1:
            break
        a_list[max_index] = max_index
    return a_list

# Calculate the final number using the process described in the solution
def calculate_state(a_list):
    if len(a_list) == 1 or gcd(*a_list) == 1:
        return 1
    return sum(a_list)

# Get an optimized way to go from state to next state efficiently
@lru_cache(maxsize=None)
def next_state(a_list):
    if len(a_list) == 1:
        return [remove_leading_zeros(a_list)[-1]]
    length = len(a_list)
    temp_list = sorted([x[1] for x in [a_list[x:x + length // gcd(*a_list)] for x in range(length)]], reverse=True)
    ans = []
    for x, y in temp_list:
        if x > y and (x - y) % gcd(x, y):
            ans.append(((x, y), (gcd(x, y), y)))
        elif x - y == gcd(x, y):
            ans.append(((x, y), (0, x)))
            break
    return sorted(ans[::-1]) if len(ans) % 2 != 0 else sorted(ans[::-1], reverse=True)

