from collections import defaultdict
from itertools import permutations

def count_different_bits(a1, a2):
    return bin(a1 ^ a2).count('1')

T = int(input())
for _ in range(T):
    N = int(input())
    connections = defaultdict(list)
    a = list(map(int, input().split()))
    for _ in range(N-1):
        A, B = map(int, input().split())
        connections[A-1].append(B-1)
        connections[B-1].append(A-1)

    result = 0
    for perm in permutations(range(N)):
        c_c, c_m = perm[0], perm[1]
        shortest_path = [0]
        for city in range(N):
            for connection in connections[city]:
                if count_different_bits(c_c, connection) != count_different_bits(perm[0], c_m):
                    shortest_path.append(count_different_bits(connection, c_m))
                else:
                    break
            else:
                continue
            break
        else:
            result += shortest_path[-1]
    print(result)
